import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        if (n < 3) {
            System.out.println(0);
            return;
        }
        // cost[t]: increase needed to make interior index t+1 a peak on its own.
        long[] cost = new long[n - 2];
        for (int i = 1; i < n - 1; i++) cost[i - 1] = Math.max(0, Math.max(a[i - 1], a[i + 1]) + 1 - a[i]);
        if (n % 2 == 1) {
            long s = 0;
            for (int t = 0; t < cost.length; t += 2) s += cost[t];
            System.out.println(s);
            return;
        }
        // Even n: some odd indices, then the following even indices; slide the switch point.
        long value = 0;
        for (int t = 1; t < cost.length; t += 2) value += cost[t];
        long answer = value;
        for (int t = 0; t + 1 < cost.length; t += 2) {
            value += cost[t] - cost[t + 1];
            answer = Math.min(answer, value);
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
